sp_widget.client_script:
function ($timeout, $sce) {
  var c = this;
  c.darkness = "";

  if (!c.options.c_color || !c.options.c_color.length) {
    c.options.c_color = '#ffd32a'; // High-visibility Canary Yellow for sweeping second hand
  }

  var audioFileName = c.options.audio_file_name || "Hospital_S.mp3"; 
  c.audioTrackUrl = $sce.trustAsResourceUrl(audioFileName);

  // FIX: Removed .tz() timezone hooks completely. 
  // Initializing empty moment() instantly reads your exact laptop hardware time.
  c.date = moment(); 
  c.majors = new Array(12);
  c.minors = new Array(60);

  var intervals = [8.0, 12.0, 16.0, 20.0];
  var audioStarted = false;

  (function tick() {
    // FIX: Continuously pulls the system time fresh from your PC
    c.date = new moment(); 

    var currentHours = c.date.hours();
    var currentMinutes = c.date.minutes();
    var currentSeconds = c.date.seconds();
    var decimalTime = currentHours + (currentMinutes / 60) + (currentSeconds / 3600);

    var targetIntervalIndex = -1;

    if (decimalTime > 8.0 && decimalTime <= 12.0) targetIntervalIndex = 1;      
    else if (decimalTime > 12.0 && decimalTime <= 16.0) targetIntervalIndex = 2; 
    else if (decimalTime > 16.0 && decimalTime <= 20.0) targetIntervalIndex = 3; 
    else targetIntervalIndex = 0;  

    var targetTime = intervals[targetIntervalIndex];
    var startTime = targetIntervalIndex === 0 ? (decimalTime > 20.0 ? 20.0 : -4.0) : intervals[targetIntervalIndex - 1];
    var adjustedCurrentTime = decimalTime;

    if (targetIntervalIndex === 0 && decimalTime > 20.0) {
      targetTime = 32.0;
    }

    var progressFactor = (adjustedCurrentTime - startTime) / (targetTime - startTime);
    if(progressFactor < 0) progressFactor = 0;
    if(progressFactor > 1) progressFactor = 1;

    if (currentMinutes === 0 && currentSeconds <= 59) {
      progressFactor = 1.0;
    } else if (currentMinutes === 1 && currentSeconds === 0) {
      progressFactor = 0.0;
    }

    // FIX: Removed the rgb background channel text generators that were conflicting with our CSS rule.

    var audio = document.getElementById("medicalAudioTimer");
    if (audio) {
      if (!audioStarted) {
        audio.play().catch(function(err){ 
          console.log("Audio waiting for user click interaction..."); 
        });
        audioStarted = true;
      }
      audio.volume = progressFactor;
    }

    $timeout(tick, 1000);
  })();
}

sp_widget.css:
.medical-clock-container {
  width: 100%;
  max-width: 400px;
  max-height: 400px;
  padding: 1.2em;
  margin: auto;
  background: #cfd8dc; /* Sleek external hardware rim ring */
  border-radius: 50%;
  box-shadow: inset 0 4px 10px rgba(0,0,0,0.35), 0 12px 36px rgba(0,0,0,0.4); 
}

.square {
  position: relative;
  width: 100%;
  height: 0;
  padding-bottom: 100%;
}

.medical-svg {
  filter: drop-shadow(0px 8px 16px rgba(0,0,0,0.45));
}

/* 100% Solid, Completely Uniform Matte Dark Charcoal Face */
.medical-face {
  fill: #262c2e !important; /* Forces a crisp, flat background color with no gradient smears */
  stroke: #1c2833;
  stroke-width: 2px;
}

/* Glowing Neon ECG Line */
.ecg-pulse {
  fill: none;
  stroke: #2ecc71; 
  stroke-width: 1.4;
  stroke-dasharray: 120;
  stroke-dashoffset: 120;
  animation: pulse-run 2.2s linear infinite;
  opacity: 0.9; 
  filter: drop-shadow(0px 0px 1.5px #2ecc71);
}

@keyframes pulse-run {
  0% { stroke-dashoffset: 120; }
  50% { stroke-dashoffset: 0; }
  100% { stroke-dashoffset: -120; }
}

/* Dial Markings Settings */
.minor {
  stroke: #b2bec3; /* Crisp silver secondary minute ticks */
  stroke-width: 0.6;
}

.major {
  stroke: #ffffff; /* Sharp solid white primary hour ticks */
  stroke-width: 1.6;
}

.second {
  stroke-width: 0.9;
}

.text-label {
  color: #2c3e50 !important;
  font-weight: 700;
  letter-spacing: 0.05em;
}

sp_widget.link:
function (scope, $element, attrs) {
  var element = $element[0];
  cacheElementSize(scope, element);

  $(window).on('resize', onWindowResize);
  setTimeout(onWindowResize, 5);

  function cacheElementSize(scope, element) {
    var elem = scope.elem = {};
    elem.w = element.offsetWidth;
    elem.h = element.offsetHeight;
    return elem;
  }

  function onWindowResize() {
    var elem = scope.elem;
    var isSizeChanged = elem.w != element.offsetWidth || elem.h != element.offsetHeight;
    if (isSizeChanged) {
      elem = cacheElementSize(scope, element);
      var w = Math.min(elem.h, elem.w);
      var clock = element.firstChild;
      if (clock && clock.style) {
        clock.style.width = w + "px";
      }
    }
  }
}
